package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_deserialize_TriageGen2Test {

    private StringArrayDeserializer deserializer;
    private JsonParser jp;
    private DeserializationContext ctxt;
    private ObjectBuffer buffer;

    @Before
    public void setUp() {
        deserializer = new StringArrayDeserializer();
        jp = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        buffer = mock(ObjectBuffer.class);
    }

    @Test
    public void testDeserialize_NonArrayToken() throws IOException {
        // Arrange
        when(jp.isExpectedStartArrayToken()).thenReturn(false);
        // Note: handleNonArray is protected, we assume it works or we mock the behavior 
        // via a spy if we needed to verify it, but here we test the branch.
        StringArrayDeserializer spyDeserializer = spy(deserializer);
        doReturn(new String[]{"not", "an", "array"}).when(spyDeserializer).handleNonArray(jp, ctxt);

        // Act
        String[] result = spyDeserializer.deserialize(jp, ctxt);

        // Assert
        assertArrayEquals(new String[]{"not", "an", "array"}, result);
        verify(jp).isExpectedStartArrayToken();
    }

    @Test
    public void testDeserialize_CustomDeserializerPresent() throws IOException {
        // Arrange
        // To trigger _elementDeserializer != null, we need a way to set it.
        // Since it's a private field, we use a spy and mock the method.
        StringArrayDeserializer spyDeserializer = spy(deserializer);
        when(jp.isExpectedStartArrayToken()).thenReturn(true);
        String[] expected = new String[]{"custom"};
        doReturn(expected).when(spyDeserializer)._deserializeCustom(jp, ctxt);

        // Act
        String[] result = spyDeserializer.deserialize(jp, ctxt);

        // Assert
        assertArrayEquals(expected, result);
        verify(spyDeserializer)._deserializeCustom(jp, ctxt);
    }

    @Test
    public void testDeserialize_StandardArrayWithMixedTypes() throws IOException {
        // Arrange
        when(jp.isExpectedStartArrayToken()).thenReturn(true);
        when(ctxt.leaseObjectBuffer()).thenReturn(buffer);

        // Mock Buffer behavior
        Object[] initialChunk = new Object[2];
        when(buffer.resetAndStart()).thenReturn(initialChunk);
        // Mock appendCompletedChunk for when ix >= chunk.length
        Object[] secondChunk = new Object[2];
        when(buffer.appendCompletedChunk(any())).thenReturn(secondChunk);
        // Mock completeAndClearBuffer
        String[] expectedResult = {"val1", null, "val3"};
        when(buffer.completeAndClearBuffer(any(), eq(3), eq(String.class))).thenReturn(expectedResult);

        // Mock JsonParser tokens
        when(jp.nextToken())
            .thenReturn(JsonToken.VALUE_STRING) // ix=0
            .thenReturn(JsonToken.VALUE_NULL)   // ix=1
            .thenReturn(JsonToken.VALUE_NUMBER_INT) // ix=2 (triggers _parseString)
            .thenReturn(JsonToken.END_ARRAY);

        when(jp.getText()).thenReturn("val1");
        // We must spy the deserializer to mock _parseString since it's a protected internal call
        StringArrayDeserializer spyDeserializer = spy(deserializer);
        doReturn("val3").when(spyDeserializer)._parseString(jp, ctxt);

        // Act
        // Since _parseString is called, we use the spy
        String[] result = spyDeserializer.deserialize(jp, ctxt);

        // Assert
        assertArrayEquals(expectedResult, result);
        verify(ctxt).returnObjectBuffer(buffer);
        verify(jp, atLeastOnce()).nextToken();
    }

    @Test
    public void testDeserialize_EmptyArray() throws IOException {
        // Arrange
        when(jp.isExpectedStartArrayToken()).thenReturn(true);
        when(ctxt.leaseObjectBuffer()).thenReturn(buffer);
        Object[] chunk = new Object[1];
        when(buffer.resetAndStart()).thenReturn(chunk);

        String[] expectedResult = new String[0];
        when(buffer.completeAndClearBuffer(any(), eq(0), eq(String.class))).thenReturn(expectedResult);

        when(jp.nextToken()).thenReturn(JsonToken.END_ARRAY);

        // Act
        String[] result = deserializer.deserialize(jp, ctxt);

        // Assert
        assertEquals(0, result.length);
        verify(ctxt).returnObjectBuffer(buffer);
    }
}
